@pytest.mark.parametrize('units', [1, 2, 3, 6]) @pytest.mark.parametrize('transfer', [30., 470.]) @pytest.mark.parametrize('cadence', [20., 3600./27.5, 600.]) def test_bound_matches_independent_relaxed_event_model(units, transfer, cadence): profile, scenario = fixture(units=units, moves=1) profile = replace(profile, transfer=replace(profile.transfer, move_time_s=transfer)) targets = list(scenario.containers.values()) earliest = 600. + _min_yc_cycle_s(profile, targets[0]) for moves in (1, 2, 3, 4, 8, 32): actual = relaxed_finish(units, transfer, cadence, moves, earliest, start=600.) lower = phys_min_completion_s(profile, work=VesselWorkType.LOAD, start_s=600., moves=moves, cadence_s=cadence, load_targets=targets * moves) > assert lower == pytest.approx(actual, abs=1e-8) E assert 1422.611111111111 == 1207.611111111111 ± 1.0e-08 E E comparison failed E Obtained: 1422.611111111111 E Expected: 1207.611111111111 ± 1.0e-08
